	\path (A)--++(0:0.3) coordinate (A');
	\tkzDefPointBy[translation=from A to A'](B) \tkzGetPoint{P}
	\path (P)--++(0:1) coordinate (Q);

	%%Point Labels
	\tkzLabelPoint[left](A){$R$};
	\tkzLabelPoint[above,yshift=3pt](B){$A$};


	%Defining angles

	\tkzMarkAngle[color=\anglecolor,fill, size=1.0](C,A,B)
	\tkzMarkRightAngle[color=\rightanglecolor, fill, size=0.4](B,C,A)
	\tkzMarkAngle[color=\vectcol, size=1.4, arrows=stealth-, \textthickness](C,A,B)
	\tkzLabelAngle[pos=2.1, yshift=-4pt, color=\textcol](C,A,B){\small $0.05\,\textrm{rad/s}$}
	\tkzLabelAngle[pos=0.7, yshift=0pt, color=\textcol](C,A,B){\small $\theta$}




	% Drawing the triangle
	\tkzDrawSegment[dashed,thin,color=\maincolor](C,B);
	\tkzDrawSegment[dashed, thin](A,C);
	\tkzDrawSegment[dashed, thin](B,A);
	\tkzDrawSegment[very thick,color=black](B,C);

	% Label the sides
	%\tkzLabelSegment[sloped, above](A,B){$z=45\,\textrm{m}$};
	%\tkzLabelSegment[below](A,C){$x$}
	\tkzLabelSegment[right](C,B){$800\,\textrm{m}$}

			% Dots
	\tkzDrawPoints[size=\psize, color=none, fill=\pcolor](B);

	% Drawing the vector down
	\tkzDrawVector[color=\vectcol, \textthickness](P,Q)


	\end{tikzpicture}
