\tkzDrawVector[color=\vectcol, \textthickness](P,Q);
\tkzLabelSegment[color=\textcol,right, xshift= 0 mm](P,Q){\small $ 4\,\textrm{km/h}$}

%%Point Labels
\tkzLabelPoint[left](A){$P$};
\tkzLabelPoint[above,yshift=3pt](B){$D$};

% Dots
